/* Editorial archive leads feature a real source record and keep placeholders explicit. */
function archive(){
 const news=route==='news',allowed=news?['notice','press','newsletter']:['business','research','academic'];
 const id=P.get('id');
 if(id){const p=posts.find(v=>v[0]===id&&allowed.includes(v[1]));return `<section class="article">${A(U(route,{board:P.get('board')||'all',q:P.get('q')||''}),'목록으로','Back to list')}<p class="eyebrow">${p?T(...types.find(v=>v[0]===p[1]).slice(1)):'NOT FOUND'}</p><h1>${p?E(T(p[3],p[4])):T('자료를 찾을 수 없습니다','Content not found.')}</h1>${p?`<div class="article-meta">GeoSR <time>${p[2]}</time>${p[5]?`<span class="badge">${T('예시','DEMO')}</span>`:''}</div><div class="article-body"><p>${p[5]?T('본문·이미지·첨부를 추가할 예시 화면입니다. 실제 게시글은 아닙니다.','A placeholder for article text, images and attachments. This is not a real article.'):T('기존 홈페이지에서 제목과 게시일을 확인했습니다. 본문과 첨부 자료는 원문을 확인한 뒤 보완하겠습니다.','The title and date are sourced from the existing website. This prototype connects representative records without migrating every article in full.')}</p>${p[0]==='notice-3091'?`<a class="download" href="assets/notice.pdf" target="_blank" rel="noopener">↓ PDF · ${T('해양수산 신기술 인증 공고 원문','Original certification notice (Korean)')}</a>`:`<div class="empty">${T('본문·첨부 자료가 들어갈 자리입니다.','Article and attachment placeholder')}</div>`}</div>`:''}</section>`;}
 const board=P.get('board')||'all',q=P.get('q')||'';
 const list=posts.filter(p=>allowed.includes(p[1])&&(board==='all'||p[1]===board)&&(p[3]+p[4]).toLowerCase().includes(q.toLowerCase()));
 const featured=board==='all'&&!q?posts.find(p=>!p[5]&&p[1]===(news?'notice':'research')):null;
 const visible=featured?list.filter(p=>p!==featured):list;
 const featuredHref=featured?U(news?'news':'research',{id:featured[0],board}):'';
 const pageTitle=news?T('GeoSR 소식','GeoSR News'):T('연구개발 및<br>주요 수행실적','Research and selected work');
 const intro=news?T('공지사항과 언론 보도, 뉴스레터를 확인할 수 있습니다.','Browse GeoSR notices, media coverage and newsletters.'):T('현장에서 시작해 연구와 학술로 이어지는 기록입니다.','Records of work spanning field projects, research and publications.');
 return `<section class="archive-hero archive-hero--${news?'news':'research'}"><div class="archive-hero-copy"><p class="eyebrow">${news?'NEWSROOM':'RESEARCH / PROJECTS / PUBLICATIONS'}</p><h1>${pageTitle}</h1><p>${intro}</p><div class="archive-hero-index"><span>${news?T('공지 · 언론 · 뉴스레터','NOTICES · MEDIA · NEWSLETTERS'):T('사업 · 연구 · 학술','PROJECTS · RESEARCH · PUBLICATIONS')}</span><span>${T('GeoSR 자료실','GEOSR ARCHIVE')}</span></div></div>${featured?`<a class="archive-featured" href="${featuredHref}"><span class="archive-featured-label">${T('주요 기록','FEATURED RECORD')}</span><time class="archive-featured-meta">${featured[2]}</time><h2>${E(T(featured[3],featured[4]))}</h2><p>${T('제목과 게시일은 기존 홈페이지에서 확인했습니다. 자세한 내용은 연결된 기록에서 볼 수 있습니다.','Title and date confirmed from the original site. Open the record for the available details.')}</p><span class="archive-featured-link">${T('기록 보기','Open record')} <i aria-hidden="true">↗</i></span></a>`:`<div class="archive-filter-state"><span>${T('자료 필터','ARCHIVE FILTER')}</span><strong>${E(q)||T(...(types.find(x=>x[0]===board)||['all','전체','All']).slice(1))}</strong><p>${T('조건에 맞는 자료를 아래 목록에서 확인하세요.','Review matching records in the list below.')}</p></div>`}</section><section class="archive archive--${news?'news':'research'}"><div class="archive-controls"><div class="filters" role="group" aria-label="${T('자료 유형','Resource types')}">${[['all','전체','All'],...types.filter(v=>allowed.includes(v[0]))].map(v=>`<a class="${board===v[0]?'active':''}" ${board===v[0]?'aria-current="page"':''} href="${U(route,{board:v[0],q})}">${T(v[1],v[2])}</a>`).join('')}</div><form class="search" action="${route}.html"><input name="lang" type="hidden" value="${L}"><input name="board" type="hidden" value="${E(board)}"><label for="q">${T('자료 검색','Search resources')}</label><div><input id="q" name="q" placeholder="${T('제목으로 검색','Search by title')}" value="${E(q)}"><button type="submit">${T('검색','Search')}</button></div></form></div><div class="archive-results-heading"><p class="result-count">${T('검색 결과','Search results')} <strong>${list.length}</strong>${T('건','records')}</p><p>${T('기존 게시물과 예시 자료를 구분해 표시합니다.','Source records and clearly marked placeholders appear together.')}</p></div><div class="records">${visible.length?rows(visible):`<div class="empty"><h2>${T('검색 결과가 없습니다','No results found.')}</h2>${A(U(route),'검색 초기화','Clear search')}</div>`}</div></section>`;
}

/* Page-specific launch layouts keep archives searchable and the source status visible. */
function business(){
 const id=Number(P.get('id'));
 if(id){
  const item=tech.find(v=>v.id===id);
  const pageTitle=item?T(item.k,item.e):T('기술 상세','Technology detail');
  const description=item?T(item.dk,item.de):T('기술별 상세 내용을 준비하고 있습니다.','Detailed information for this technology is being prepared.');
  const media=filmSlot('business-technology-'+id,pageTitle,T('자료를 확인한 뒤 이미지를 추가합니다','Images will be added after source review'));
  return `<section class="detail-hero"><div class="detail-hero-copy"><p class="eyebrow">TECHNOLOGY / ${id}</p><h1>${pageTitle}</h1><p>${description}</p><span class="source-status">${T('기술 자료 정리 중','TECHNICAL SOURCE REVIEW IN PROGRESS')}</span></div>${media}</section><section class="detail-body"><div><span class="eyebrow">OVERVIEW</span><h2>${T('기술과 자료를<br>함께 살펴봅니다','Explore the method<br>and its source')}</h2></div><div><p>${T('세부 방법과 적용 범위는 확인된 자료를 바탕으로 안내하겠습니다.','Methods and application details will be published after review against the source material.')}</p><h3>${T('관련 기록','Related records')}</h3>${rows(posts.filter(p=>p[1]==='research').slice(0,3))}</div></section><section class="detail-return">${A(U('business'),'기술 분야 전체 보기','Browse all fields','plain-arrow')}</section>`;
 }
 const axes=['관측·측량','해양·수환경','생태·분석','모델·재해','위성·공간정보'];
 const axesEnglish=['Survey and measurement','Marine and aquatic environments','Ecology and analysis','Models and hazards','Satellite and spatial data'];
 const initialAxis=Math.max(0,Math.min(axes.length-1,Number(P.get('axis'))||0));
 const groupShell=businessGroups.map((group,index)=>`<button type="button" class="capability-axis" data-capability-axis="${index}" data-solution-ids="${group.ids.join(',')}" data-axis-summary="${E(T(group.bodyK,group.bodyE))}" aria-pressed="${index===initialAxis}"><span class="capability-axis-number">0${index+1}</span><span class="capability-axis-name">${T(axes[index],axesEnglish[index])}</span></button>`).join('');
 return `<section class="capability-explorer" data-capability-root data-initial-axis="${initialAxis}" aria-labelledby="business-title"><div class="capability-intro"><p class="capability-kicker">GEOSR / EXPERTISE</p><h1 id="business-title">${T('기술과 솔루션','Expertise')}</h1><p>${T('현장 관측부터 환경 분석과 공간정보 기술까지 주요 분야를 소개합니다','Explore GeoSR technologies in field observation, environmental analysis and spatial information.')}</p></div><div class="capability-workspace"><nav class="capability-axis-rail" aria-label="${T('기술 분야 선택','Browse by technology area')}">${groupShell}</nav><svg class="capability-relationship-map" data-capability-map aria-hidden="true" preserveAspectRatio="none"></svg><div class="capability-selected-media" role="img" aria-label="${T('분야 영상 준비 중','Field video in preparation')}"><span>${T('분야 영상 준비 중','FIELD VIDEO IN PREPARATION')}</span></div><section class="capability-detail" aria-live="polite"><span class="capability-detail-number" data-capability-number>0${initialAxis+1} / 05</span><h2 data-capability-title>${T(axes[initialAxis],axesEnglish[initialAxis])}</h2><p data-capability-summary>${T(businessGroups[initialAxis].bodyK,businessGroups[initialAxis].bodyE)}</p><nav class="capability-related-links" data-capability-links aria-label="${T('관련 기술 링크','Related technology links')}"></nav><p class="capability-source-note">${T('기술명은 기존 홈페이지 자료에서 확인했습니다.','Technology titles are verified against the existing GeoSR index.')}</p></section><div class="capability-technology-rail" id="capability-technology-rail" tabindex="0" role="region" aria-label="${T('기존 홈페이지에서 확인한 21개 기술명','21 technology titles verified from the existing GeoSR index')}"><div class="capability-technology-list" id="capability-technology-list"></div></div></div></section>`;
}
function archive(){
 const news=route==='news',allowed=news?['notice','press','newsletter']:['business','research','academic'];
 const id=P.get('id');
 if(id){
  const item=posts.find(v=>v[0]===id&&allowed.includes(v[1]));
  return `<article class="article"><a class="article-back" href="${U(route,{board:P.get('board')||'all',q:P.get('q')||'',year:P.get('year')||'all',mock:P.get('mock')||''})}">${T('목록으로','Back to records')}</a><p class="eyebrow">${item?T(...types.find(v=>v[0]===item[1]).slice(1)):'NOT FOUND'}</p><h1>${item?E(T(item[3],item[4])):T('자료를 찾을 수 없습니다','Record not found')}</h1>${item?`<div class="article-meta"><span>${item[5]?T('목업','MOCKUP'):T('원문 기반','SOURCE RECORD')}</span><time datetime="${E(item[2])}">${E(item[2])}</time></div><div class="article-body"><p>${item[5]?T('화면 구성과 탐색 방식을 보여주는 목업 항목입니다. 실제 게시물은 아닙니다','A mock entry for the archive layout. It is not a published article'):T('기존 홈페이지에서 제목과 게시일을 확인한 자료입니다','The title and date were confirmed on the existing GeoSR website')}</p><div class="article-pending">${item[5]?T('본문과 첨부 자료는 목업 범위에 포함되지 않습니다','Full text and attachments are outside this mock entry'):T('본문과 첨부 자료는 원문 확인 후 추가합니다','Full text and attachments will be added after source review')}</div></div>`:''}</article>`;
 }
 const board=P.get('board')||'all',q=(P.get('q')||'').trim(),year=P.get('year')||'all',includeMocks=P.get('mock')==='1';
 const list=posts.filter(p=>allowed.includes(p[1])&&(includeMocks||!p[5])&&(board==='all'||p[1]===board)&&(year==='all'||p[2].startsWith(year))&&(p[3]+' '+p[4]).toLocaleLowerCase().includes(q.toLocaleLowerCase()));
 const featured=board==='all'&&year==='all'&&!q?posts.find(p=>!p[5]&&p[1]===(news?'notice':'research')):null;
 const visible=featured?list.filter(p=>p!==featured):list;
 const heading=news?T('GeoSR 소식','GeoSR News'):T('연구와 성과','Research & results');
 const lead=news?T('GeoSR의 연구와 사업 소식을 전합니다','News and project updates from GeoSR'):T('GeoSR의 연구개발과 주요 수행 실적을 소개합니다','Research and selected project work at GeoSR');
 const kinds=news?T('공지 · 언론 보도 · 뉴스레터','NOTICES · MEDIA · NEWSLETTERS'):T('사업 · 연구 · 학술','PROJECTS · RESEARCH · PUBLICATIONS');
 const years=[...new Set(posts.filter(p=>allowed.includes(p[1])&&!p[5]&&/^\d{4}/.test(p[2])).map(p=>p[2].slice(0,4)))].sort((a,b)=>b.localeCompare(a));
 const queryState={board,q,year,mock:includeMocks?'1':''};
 const mockToggle=U(route,{board,q,year,...(includeMocks?{}:{mock:'1'})});
 return `<section class="archive-hero archive-hero--${news?'news':'research'}"><div class="archive-hero-copy"><nav class="archive-breadcrumb" aria-label="${T('현재 위치','Breadcrumb')}"><a href="${U('index')}">${T('홈','Home')}</a><span aria-hidden="true">/</span><span>${news?T('소식','News'):T('연구와 성과','Research')}</span></nav><p class="eyebrow">${news?'GEOSR / NEWSROOM':'GEOSR / RESEARCH'}</p><h1>${heading}</h1><p>${lead}</p><div class="archive-hero-index"><span>${kinds}</span><span>${T('자료 찾아보기','BROWSE RECORDS')}</span></div></div>${featured?`<a class="archive-featured" href="${U(route,{id:featured[0],...queryState})}"><span class="archive-featured-label">${T(news?'주요 소식':'주요 연구','FEATURED')}</span><h2>${E(T(featured[3],featured[4]))}</h2><time class="archive-featured-meta" datetime="${E(featured[2])}">${E(featured[2])}</time><span class="archive-featured-link">${T('기록 열기','Open record')} <i aria-hidden="true">→</i></span></a>`:`<div class="archive-filter-state"><span>${T('현재 선택','CURRENT SELECTION')}</span><strong>${E(q)||T(...(types.find(x=>x[0]===board)||['all','전체','All']).slice(1))}</strong><p>${T('아래에서 조건에 맞는 자료를 확인하세요','Review matching records below')}</p></div>`}</section><section class="archive archive--${news?'news':'research'}"><div class="archive-controls"><nav class="filters" role="group" aria-label="${T('자료 유형 선택','Choose a record type')}">${[['all','전체','All'],...types.filter(v=>allowed.includes(v[0]))].map(v=>`<a class="${board===v[0]?'active':''}" ${board===v[0]?'aria-current="page"':''} href="${U(route,{board:v[0],q,year,mock:includeMocks?'1':''})}">${T(v[1],v[2])}</a>`).join('')}</nav><form class="search" action="${route}.html"><input name="lang" type="hidden" value="${L}"><input name="board" type="hidden" value="${E(board)}"><input name="mock" type="hidden" value="${includeMocks?'1':''}"><label for="q">${T('자료 검색','Search records')}</label><div><input id="q" name="q" placeholder="${T('제목을 입력하세요','Enter a title')}" value="${E(q)}"><button type="submit">${T('검색','Search')}</button></div><label class="archive-year-label" for="year-filter">${T('연도','Year')}</label><select id="year-filter" name="year"><option value="all" ${year==='all'?'selected':''}>${T('전체 연도','All years')}</option>${years.map(value=>`<option value="${value}" ${year===value?'selected':''}>${value}</option>`).join('')}</select></form></div><div class="archive-results-heading"><p class="result-count">${T('현재 목록','Current list')} <strong>${list.length}</strong> ${T('건','records')}</p><a class="archive-mock-toggle" href="${mockToggle}" aria-pressed="${includeMocks}">${includeMocks?T('목업 항목 숨기기','Hide mock entries'):T('목업 항목 보기','Show mock entries')}</a></div><div class="records">${visible.length?rows(visible):`<div class="empty"><h2>${T('검색 결과가 없습니다','No matching records')}</h2><a href="${U(route)}">${T('검색 조건 지우기','Clear search')}</a></div>`}</div></section>`;
}

